import sys
import re
from datetime import datetime
from pathlib import Path

def evaluate_expression(expr):
    try:
        # Remove all whitespace and evaluate
        expr = re.sub(r'\s+', '', expr)
        return int(eval(expr))
    except:
        return None

def main():
    template_path = Path('scores_template.html')
    log_path = Path('score_report.log')

    template = template_path.read_text()
    rows = []
    lines = []
    line_num = 0

    for line in sys.stdin:
        line_num += 1
        line = line.strip()
        if not line:
            continue

        parts = re.split(r'=+', line, maxsplit=1)
        if len(parts) < 2:
            with log_path.open('a') as f:
                try:
                    f.write(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} WARN: line {line_num} missing equals\n")
                except:
                    print(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} WARN: line {line_num} missing equals", file=sys.stderr)
            continue

        name = parts[0].strip()
        expr = parts[1].strip()
        value = evaluate_expression(expr)

        if value is not None:
            rows.append(f"<tr><td>{name}</td><td>{value}</td></tr>")
        else:
            with log_path.open('a') as f:
                try:
                    f.write(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} ERROR: line {line_num} invalid expression\n")
                except:
                    print(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} ERROR: line {line_num} invalid expression", file=sys.stderr)

    if not rows:
        rows_str = "<tr><td colspan=\"2\">No scores</td></tr>"
    else:
        rows_str = ''.join(rows)

    output = template.replace('{{rows}}', rows_str)
    print(output)

if __name__ == "__main__":
    main()

