import sys
import re
from datetime import datetime

def process_input():
    template = None
    try:
        with open('scores_template.html', 'r') as f:
            template = f.read()
    except IOError:
        sys.stderr.write("Error: Could not read scores_template.html\n")
        return

    rows = []
    log_lines = []
    line_num = 0

    for line in sys.stdin:
        line_num += 1
        line = line.strip()
        if not line:
            continue

        parts = line.split('=', 1)
        if len(parts) != 2:
            log_lines.append(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} ERROR: line {line_num} invalid input")
            continue

        name = parts[0].strip()
        value_str = parts[1].strip()

        if value_str.isdigit():
            value = int(value_str)
            rows.append(f"<tr><td>{name}</td><td>{value}</td></tr>")
        else:
            log_lines.append(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')} ERROR: line {line_num} invalid input")

    log_file = 'score_report.log'
    try:
        with open(log_file, 'a') as f:
            for line in log_lines:
                f.write(line + '\n')
    except IOError:
        sys.stderr.write("Error: Could not write to score_report.log\n")
        for line in log_lines:
            sys.stderr.write(line + '\n')

    if not rows:
        rows_str = "<tr><td colspan=\"2\">No scores</td></tr>"
    else:
        rows_str = ''.join(rows)

    output = template.replace('{{rows}}', rows_str)
    print(output)

process_input()
